#!/usr/bin/env bash
# Reproducible optional source rebuild. Ordinary npm builds use checked-in JS.
set -euo pipefail
cd "$(dirname "$0")/.."
compiler="${EMXX:-em++}"
version="$("$compiler" --version | head -1)"
if [[ "$version" != *'3.1.64'* ]]; then echo 'Use Emscripten 3.1.64 (EMXX=/path/to/em++).' >&2; exit 1; fi
target=packages/engine/src/variants/mcr-runtime.ts
scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT
"$compiler" packages/engine/vendor/mcr/{fan_calculator.cpp,shanten.cpp,bridge.cpp} -std=c++17 -O3 -fno-exceptions -fno-rtti -sWASM=0 -sSINGLE_FILE=1 -sMODULARIZE=1 -sEXPORT_ES6=1 -sWASM_ASYNC_COMPILATION=0 -sENVIRONMENT=web,worker -sEXPORTED_FUNCTIONS='["_mcr_input","_mcr_output","_mcr_size","_mcr_score","_mcr_name","_mcr_value","_mcr_distance"]' -sEXPORTED_RUNTIME_METHODS='["UTF8ToString","HEAP32"]' -sINITIAL_MEMORY=16777216 -sSTACK_SIZE=1048576 -o "$scratch/runtime.js"
{ printf '%s\n' '// @ts-nocheck' '/*! @license'; cat packages/engine/vendor/mcr/LICENSE; printf '%s\n' ' */' '/* Generated by scripts/build-mcr-scorer.sh, Emscripten 3.1.64.' ' * MIT scorer: Jeff Wang, 2016–2023. See ../../vendor/mcr/LICENSE and NOTICE.md.' ' * Pinned EMA/WMO 2006 81-pattern profile. No network or runtime dependencies. */'; cat "$scratch/runtime.js"; } | sed 's/[[:blank:]]*$//' > "$target"
